head.b:skin:
body { 
  font-family: 'Inter', sans-serif; 
  background-color: #0f172a;
  margin: 0 !important;
  padding: 0 !important;
  -webkit-font-smoothing: antialiased;
}
#navbar, .navbar, .GHuuof, #b-navbar, .blog-pager, .post-footer, 
.comments, .header-widget, .mobile-link-button, .sidebar, .date-header { 
  display: none !important; 
}

.custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }
.custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
.custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; border-radius: 10px; }
.custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #475569; }

.widget { margin: 0; padding: 0; }

@keyframes float {
  0% { transform: translateY(0px); }
  50% { transform: translateY(-5px); }
  100% { transform: translateY(0px); }
}
.animate-float { animation: float 4s ease-in-out infinite; }

@keyframes seek-pop {
  0% { transform: scale(0.75); opacity: 0; }
  25% { transform: scale(1.05); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}
.seek-pop { animation: seek-pop 0.18s ease-out forwards; }

body.script:
//
  const { useState, useEffect, useMemo, useRef, Fragment } = React;

  // ==========================================
  // BACKEND CONFIGURATION
  // Update this to your deployed Vercel backend URL
  // ==========================================
  const BACKEND_CONFIG = {
    apiBaseUrl: window.location.origin.includes('localhost')
      ? 'http://localhost:3000'
      : 'https://your-vercel-domain.vercel.app', // <-- CHANGE TO YOUR DEPLOYED VERCEL URL
    courseId: 'acs-frb-26'
  };

  const firebaseConfig = {
    apiKey: "AIzaSyCNTSiVxlLr1Ipjp8MGA5A3mpKN370cStA",
    authDomain: "mystudytracker-693d3.firebaseapp.com",
    projectId: "mystudytracker-693d3",
    storageBucket: "mystudytracker-693d3.firebasestorage.app",
    messagingSenderId: "172652188741",
    appId: "1:172652188741:web:f100cff62dd097b2763f2c",
    measurementId: "G-QG3PTZF7EQ"
  };

  if (!firebase.apps.length) {
    firebase.initializeApp(firebaseConfig);
  }
  const auth = firebase.auth();
  const db = firebase.firestore();
  const googleProvider = new firebase.auth.GoogleAuthProvider();

  // ==========================================
  // AUTHENTICATED PLAYBACK REQUEST FUNCTION
  // ==========================================
  async function requestPlaybackAuthorization(videoIdentifier, courseId = BACKEND_CONFIG.courseId) {
    const currentUser = auth.currentUser;
    if (!currentUser) {
      throw new Error('AUTH_REQUIRED');
    }

    // Get short-lived Firebase ID Token for the user
    const idToken = await currentUser.getIdToken(false);

    const response = await fetch(`${BACKEND_CONFIG.apiBaseUrl}/api/video/playback`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${idToken}`
      },
      body: JSON.stringify({
        videoId: videoIdentifier,
        courseId: courseId,
        videoPath: videoIdentifier
      })
    });

    const data = await response.json();

    if (!response.ok || !data.success) {
      const err = new Error(data.message || 'Authorization failed');
      err.code = data.error || 'AUTH_FAILED';
      err.status = response.status;
      throw err;
    }

    return data; // { success: true, playbackUrl: "...", expiresAt: 1234567890 }
  }

  // Lecture Data
  const lectureData = [
    {
      name: "Physics 1st Paper",
      chapters: [
        {
          name: "Chapter 1_ ভৌতজগত ও পরিমাপ",
          links: [
            { text: "Class 1", url: "https://vz-cb5996f0-784.b-cdn.net/190baa47-1c4d-458e-9755-4673aa6293c3/playlist.m3u8" }
          ]
        },
        {
          name: "Chapter 2_ ভেক্টর",
          links: [
            { text: "Class 1", url: "https://vz-cb5996f0-784.b-cdn.net/2029ac2a-3771-425b-bc8f-80c68bf3d0b9/playlist.m3u8" },
            { text: "Class 2", url: "https://vz-cb5996f0-784.b-cdn.net/4f02929f-3ade-4c71-bb32-56d77b070818/playlist.m3u8" },
            { text: "Class 3", url: "https://vz-cb5996f0-784.b-cdn.net/d2fab479-c570-4e59-b926-8685acdbb374/playlist.m3u8" }
          ]
        }
      ]
    },
    {
      name: "Higher Math 1st Paper",
      chapters: [
        {
          name: "Chapter 1_ ম্যাট্রিক্স ও নির্ণায়ক",
          links: [
            { text: "Class 1 (YouTube)", url: "https://www.youtube.com/watch?v=67B9P3TgKa8" }
          ]
        },
        {
          name: "Chapter 2_ ভেক্টর",
          links: [
            { text: "Class 1", url: "https://vz-cb5996f0-784.b-cdn.net/960bd5b1-d08c-465f-b14b-60fc09b9340e/playlist.m3u8" }
          ]
        }
      ]
    }
  ];

  const cleanUrl = (url) => {
    if (!url) return '';
    const value = String(url).trim();
    const markdownMatch = value.match(/\]\((https?:\/\/[^)]+)\)/);
    return markdownMatch ? markdownMatch[1] : value;
  };

  const makeStableId = (value) => {
    let hash = 2166136261;
    for (let i = 0; i < value.length; i++) {
      hash ^= value.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return 'v_' + (hash >>> 0).toString(36) + '_' + value.length.toString(36);
  };

  const getVideoId = (url) => {
    const clean = cleanUrl(url);
    if (!clean) return null;

    if (/\.m3u8(?:$|\?)/i.test(clean)) {
      return makeStableId(clean);
    }

    try {
      const urlObj = new URL(clean);
      let videoId = null;

      if (urlObj.hostname === 'youtu.be') {
        videoId = urlObj.pathname.replace(/^\//, '').split('/')[0];
      } else if (urlObj.hostname.includes('youtube.com')) {
        videoId = urlObj.searchParams.get('v');

        if (!videoId) {
          const match = urlObj.pathname.match(/\/(?:embed|v|shorts)\/([^/?]+)/);
          videoId = match ? match[1] : null;
        }
      }

      return videoId ? videoId.split('&')[0] : null;
    } catch (e) {
      const match = clean.match(/(?:https?:\/\/)?(?:www\.)?(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|shorts\/|watch\?v=|watch\?.+&v=))([^&?#]+)/i);
      return match ? match[1] : null;
    }
  };

  const isValidVideoId = (id) => typeof id === 'string' && id.length > 0;

  const formatSubjectTitle = (title) => {
    const parts = title.split(/(1st|2nd|3rd|4th)/);
    return parts.map((part, i) => {
      if (['1st', '2nd', '3rd', '4th'].includes(part)) {
        return <Fragment key={i}>{part.charAt(0)}<sup className="text-[0.7em]">{part.slice(1)}</sup></Fragment>;
      }
      return part;
    });
  };

  const formatChapterName = (name) => name.replace(/_(\s)?/, ' ');

  const Icons = {
    Play: () => <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>,
    Check: () => <svg className="w-5 h-5 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="3"><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7"/></svg>,
    Dashboard: () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zm10 0a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zm10 0a2 2 0 012-2h2a2 2 0 012 2v8a2 2 0 01-2 2h-2a2 2 0 01-2-2v-8z"/></svg>,
    Library: () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"/></svg>,
    ChevronDown: ({open}) => <svg className={`w-5 h-5 transition-transform duration-300 ${open ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"/></svg>,
    Lock: () => <svg className="w-8 h-8 text-amber-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
  };

  const CircularProgress = ({ completed, total, size = "sm" }) => {
    const percentage = total > 0 ? Math.min(100, Math.round((completed / total) * 100)) : 0;
    const isLarge = size === "lg";
    const radius = isLarge ? 45 : 16;
    const strokeWidth = isLarge ? 8 : 3;
    const circumference = 2 * Math.PI * radius;
    const strokeDashoffset = circumference - (percentage / 100) * circumference;

    return (
      <div className={`flex items-center ${isLarge ? 'flex-col space-y-4' : 'space-x-3 bg-white/5 px-3 py-1.5 rounded-full border border-white/10 backdrop-blur-sm'}`}>
        <div className={`relative flex items-center justify-center ${isLarge ? 'w-32 h-32' : 'w-9 h-9'}`}>
          <svg className="w-full h-full transform -rotate-90 filter drop-shadow-lg">
            <circle cx="50%" cy="50%" r={radius} stroke="currentColor" strokeWidth={strokeWidth} className="text-slate-800" fill="transparent" />
            <circle cx="50%" cy="50%" r={radius} stroke="url(#gradient)" strokeWidth={strokeWidth} className="transition-all duration-1000 ease-out" fill="transparent" strokeDasharray={circumference} strokeDashoffset={strokeDashoffset} strokeLinecap="round" />
            <defs>
              <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#06b6d4" />
                <stop offset="100%" stopColor="#3b82f6" />
              </linearGradient>
            </defs>
          </svg>
          <div className="absolute flex flex-col items-center justify-center">
            <span className={`${isLarge ? 'text-3xl font-extrabold text-white' : 'text-[10px] font-bold text-white'}`}>{percentage}%</span>
          </div>
        </div>
        <div className={`${isLarge ? 'text-center' : 'text-xs text-slate-300 font-medium'}`}>
          {isLarge && <div className="text-slate-400 text-sm font-medium uppercase tracking-wider mb-1">Completed</div>}
          <span className={`font-bold ${isLarge ? 'text-2xl text-white' : 'text-cyan-400'}`}>{completed}</span>
          <span className={isLarge ? 'text-lg text-slate-500 mx-1' : 'text-slate-500 mx-1'}>/</span>
          <span className={isLarge ? 'text-lg text-slate-400' : 'text-slate-400'}>{total}</span>
          {!isLarge && " Done"}
        </div>
      </div>
    );
  };

  const AccordionItem = ({ title, progressInfo, children, isSubject = false, isOpen, onToggle, itemRef }) => {
    const baseClasses = isSubject
      ? 'bg-gradient-to-r from-slate-800/80 to-slate-900/80 backdrop-blur-md border border-slate-700/50 shadow-xl rounded-2xl'
      : 'bg-slate-800/40 border border-slate-700/30 rounded-xl';
    const headerClasses = isSubject
      ? 'text-[15px] sm:text-lg font-bold text-white'
      : 'text-sm sm:text-base font-semibold text-slate-200';

    return (
      <div ref={itemRef} className={`mb-3 overflow-hidden transition-all duration-500 ease-in-out ${baseClasses} ${isOpen ? 'ring-1 ring-cyan-500/10' : ''}`}>
        <button type="button" onClick={onToggle} aria-expanded={isOpen}
          className={`w-full flex items-center justify-between p-3 sm:p-4 hover:bg-white/5 transition-colors focus:outline-none ${isOpen && isSubject ? 'border-b border-slate-700/50' : ''}`}>
          <span className={`flex-1 text-left pr-2 ${headerClasses}`}>{title}</span>
          <div className="flex items-center space-x-3">
            {progressInfo && <CircularProgress completed={progressInfo.completed} total={progressInfo.total} />}
            <div className={`p-1.5 rounded-full bg-white/5 transition-all duration-300 ${isOpen ? 'bg-cyan-500/20 text-cyan-400 rotate-180' : 'text-slate-400'}`}>
              <Icons.ChevronDown open={isOpen} />
            </div>
          </div>
        </button>
        <div className={`grid transition-[grid-template-rows,opacity] duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] ${isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'}`}>
          <div className="min-h-0 overflow-hidden">
            <div className={`p-2 sm:p-4 ${isSubject ? 'bg-slate-900/40' : 'bg-black/20'}`}>
              {children}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // ==========================================
  // UNIVERSAL PLAYER WITH AUTHENTICATED BUNNY HLS
  // ==========================================
  const UniversalPlayer = ({ video, user, onMarkWatched, onRequireLogin }) => {
    const videoRef = useRef(null);
    const ytPlayerRef = useRef(null);
    const hlsRef = useRef(null);
    const plyrRef = useRef(null);
    const hasMarkedRef = useRef(false);
    const currentIdRef = useRef(null);
    const seekTimerRef = useRef(null);
    const retryCountRef = useRef(0);

    const [ytReady, setYtReady] = useState(false);
    const [seekOverlay, setSeekOverlay] = useState(null);
    const [playerState, setPlayerState] = useState({
      loading: false,
      error: null,
      errorType: null
    });

    useEffect(() => {
      hasMarkedRef.current = false;
      currentIdRef.current = video ? getVideoId(video.url) : null;
      retryCountRef.current = 0;
      setPlayerState({ loading: false, error: null, errorType: null });
    }, [video]);

    const showSeekOverlay = (text, side = 'center') => {
      if (seekTimerRef.current) clearTimeout(seekTimerRef.current);
      setSeekOverlay({ text, side });
      seekTimerRef.current = setTimeout(() => setSeekOverlay(null), 650);
    };

    useEffect(() => () => {
      if (seekTimerRef.current) clearTimeout(seekTimerRef.current);
    }, []);

    const markCompleted = () => {
      const id = currentIdRef.current;
      if (!isValidVideoId(id) || hasMarkedRef.current) return;
      hasMarkedRef.current = true;
      onMarkWatched(id);
    };

    // Load YouTube API
    useEffect(() => {
      if (window.YT && window.YT.Player) { setYtReady(true); return; }
      if (document.getElementById('youtube-iframe-api')) {
        const previous = window.onYouTubeIframeAPIReady;
        window.onYouTubeIframeAPIReady = () => {
          if (typeof previous === 'function') previous();
          setYtReady(true);
        };
        return;
      }
      const tag = document.createElement('script');
      tag.id = 'youtube-iframe-api';
      tag.src = 'https://www.youtube.com/iframe_api';
      window.onYouTubeIframeAPIReady = () => setYtReady(true);
      document.head.appendChild(tag);
    }, []);

    // Authenticated Bunny CDN HLS Playback Function
    async function playAuthenticatedBunnyVideo(videoTarget) {
      const media = videoRef.current;
      if (!media || !videoTarget) return;

      // 1. Destroy previous player instances cleanly
      if (plyrRef.current) {
        try { plyrRef.current.destroy(); } catch (e) {}
        plyrRef.current = null;
      }
      if (hlsRef.current) {
        try { hlsRef.current.destroy(); } catch (e) {}
        hlsRef.current = null;
      }

      // Verify user is authenticated
      if (!auth.currentUser) {
        setPlayerState({
          loading: false,
          error: 'Please log in with your student Google account to view this protected class.',
          errorType: 'AUTH_REQUIRED'
        });
        return;
      }

      setPlayerState({ loading: true, error: null, errorType: null });

      try {
        // 2. Request short-lived signed playback authorization from backend
        const clean = cleanUrl(videoTarget.url);
        const authResult = await requestPlaybackAuthorization(clean, BACKEND_CONFIG.courseId);
        const authorizedUrl = authResult.playbackUrl;

        setPlayerState({ loading: false, error: null, errorType: null });

        // 3. Initialize HLS.js or native HLS
        if (window.Hls && window.Hls.isSupported()) {
          const hls = new window.Hls({
            xhrSetup: (xhr) => {
              xhr.withCredentials = false;
            },
            enableWorker: true,
            lowLatencyMode: false
          });
          hlsRef.current = hls;

          hls.loadSource(authorizedUrl);
          hls.attachMedia(media);

          // 4. Handle manifest parsed & initialize Plyr
          hls.on(window.Hls.Events.MANIFEST_PARSED, () => {
            const availableQualities = hls.levels.map(l => l.height);
            availableQualities.unshift(0);

            plyrRef.current = new window.Plyr(media, {
              controls: [
                'play-large', 'play', 'progress', 'current-time',
                'duration', 'captions', 'settings', 'fullscreen'
              ],
              settings: ['captions', 'quality', 'speed'],
              speed: { selected: 1, options: [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] },
              quality: {
                default: 0,
                options: availableQualities,
                forced: true,
                onChange: (qualityHeight) => {
                  if (qualityHeight === 0) hls.currentLevel = -1;
                  else hls.currentLevel = hls.levels.findIndex(l => l.height === qualityHeight);
                }
              },
              i18n: { qualityLabel: { 0: 'Auto' } }
            });

            media.play().catch(() => {});
          });

          // 5. Intelligent error handling & token expiry refresh (without infinite loops)
          hls.on(window.Hls.Events.ERROR, async (event, data) => {
            if (data.fatal) {
              const responseCode = data.response?.code;

              // If token expired or forbidden (403/401), request a fresh authorized token
              if ((responseCode === 403 || responseCode === 401) && retryCountRef.current < 2) {
                retryCountRef.current += 1;
                try {
                  const refreshed = await requestPlaybackAuthorization(clean, BACKEND_CONFIG.courseId);
                  hls.loadSource(refreshed.playbackUrl);
                  hls.startLoad();
                  return;
                } catch (refreshErr) {
                  setPlayerState({
                    loading: false,
                    error: 'Your video playback authorization has expired. Please refresh the class.',
                    errorType: 'TOKEN_EXPIRED'
                  });
                  hls.destroy();
                  return;
                }
              }

              switch (data.type) {
                case window.Hls.ErrorTypes.NETWORK_ERROR:
                  if (retryCountRef.current < 2) {
                    retryCountRef.current += 1;
                    hls.startLoad();
                  } else {
                    setPlayerState({
                      loading: false,
                      error: 'Network connection issue while loading class stream. Please check your internet.',
                      errorType: 'NETWORK_ERROR'
                    });
                    hls.destroy();
                  }
                  break;
                case window.Hls.ErrorTypes.MEDIA_ERROR:
                  hls.recoverMediaError();
                  break;
                default:
                  setPlayerState({
                    loading: false,
                    error: 'Unable to stream this video. Please try again later.',
                    errorType: 'PLAYBACK_ERROR'
                  });
                  hls.destroy();
                  break;
              }
            }
          });

        } else if (media.canPlayType('application/vnd.apple.mpegurl')) {
          // Native iOS / Safari HLS support
          media.src = authorizedUrl;
          plyrRef.current = new window.Plyr(media, {
            settings: ['captions', 'speed'],
            speed: { selected: 1, options: [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] }
          });
          media.play().catch(() => {});
        }

      } catch (error) {
        let message = 'Unable to authorize class playback.';
        if (error.code === 'AUTH_REQUIRED' || error.message === 'AUTH_REQUIRED') {
          message = 'Please log in with your Google account to access this course.';
        } else if (error.code === 'ACCESS_DENIED' || error.status === 403) {
          message = 'Course access restricted. Your account is not enrolled in this batch.';
        } else if (error.code === 'VIDEO_NOT_FOUND' || error.status === 404) {
          message = 'This lecture is currently unavailable.';
        }

        setPlayerState({
          loading: false,
          error: message,
          errorType: error.code || 'AUTH_ERROR'
        });
      }
    }

    // Trigger HLS when video or auth changes
    useEffect(() => {
      if (!video) return;
      const clean = cleanUrl(video.url);
      if (!/\.m3u8(?:$|\?)/i.test(clean)) return;

      playAuthenticatedBunnyVideo(video);

      return () => {
        const media = videoRef.current;
        if (media) {
          try { media.playbackRate = 1; media.pause(); } catch (e) {}
        }
        if (plyrRef.current) { try { plyrRef.current.destroy(); } catch (e) {} plyrRef.current = null; }
        if (hlsRef.current) { try { hlsRef.current.destroy(); } catch (e) {} hlsRef.current = null; }
      };
    }, [video, user]);

    // YouTube Player
    useEffect(() => {
      if (!video || !ytReady) return;
      const clean = cleanUrl(video.url);
      if (/\.m3u8(?:$|\?)/i.test(clean)) return;
      const videoId = getVideoId(clean);
      if (!videoId) return;

      const timer = setTimeout(() => {
        if (!window.YT || !window.YT.Player) return;
        ytPlayerRef.current = new window.YT.Player('yt-player', {
          videoId,
          playerVars: { autoplay: 1, rel: 0, modestbranding: 1, playsinline: 1 },
          events: {
            onReady: (event) => { try { event.target.playVideo(); } catch (e) {} },
            onStateChange: (event) => { if (event.data === window.YT.PlayerState.ENDED) markCompleted(); }
          }
        });
      }, 50);

      return () => {
        clearTimeout(timer);
        if (ytPlayerRef.current) { try { ytPlayerRef.current.destroy(); } catch (e) {} ytPlayerRef.current = null; }
      };
    }, [video, ytReady]);

    // YouTube 90% checker
    useEffect(() => {
      if (!video || !ytReady) return;
      if (/\.m3u8(?:$|\?)/i.test(cleanUrl(video.url))) return;
      const interval = setInterval(() => {
        const player = ytPlayerRef.current;
        if (!player || typeof player.getCurrentTime !== 'function') return;
        try {
          const current = player.getCurrentTime();
          const duration = player.getDuration();
          if (duration > 0 && current / duration >= 0.90) markCompleted();
        } catch (e) {}
      }, 3000);
      return () => clearInterval(interval);
    }, [video, ytReady]);

    if (!video) {
      return (
        <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 bg-slate-900/50 backdrop-blur-sm">
          <Icons.Play />
          <h3 className="mt-4 text-lg font-medium text-slate-300">Select a class to start learning</h3>
        </div>
      );
    }

    const isHLS = /\.m3u8(?:$|\?)/i.test(cleanUrl(video.url));

    const handleHlsDoubleClick = (e) => {
      const media = videoRef.current;
      if (!media || !Number.isFinite(media.duration)) return;
      const rect = media.getBoundingClientRect();
      const x = e.clientX - rect.left;
      e.preventDefault();
      e.stopPropagation();
      if (x < rect.width / 2) {
        media.currentTime = Math.max(0, media.currentTime - 10);
        showSeekOverlay('−10s', 'left');
      } else {
        media.currentTime = Math.min(media.duration, media.currentTime + 10);
        showSeekOverlay('+10s', 'right');
      }
    };

    const handleHlsPointerDown = (e) => {
      const media = videoRef.current;
      if (!media) return;
      const rect = media.getBoundingClientRect();
      const x = e.clientX - rect.left;
      if (x > rect.width * 0.55) {
        try { media.playbackRate = 2; showSeekOverlay('2×', 'right'); } catch (err) {}
      }
    };

    const handleHlsPointerUp = () => {
      const media = videoRef.current;
      if (!media) return;
      try {
        if (media.playbackRate === 2) { media.playbackRate = 1; showSeekOverlay('1×', 'right'); }
      } catch (e) {}
    };

    const overlayPosition = seekOverlay?.side === 'left'
      ? 'left-10 sm:left-20'
      : seekOverlay?.side === 'right'
        ? 'right-10 sm:right-20'
        : 'left-1/2 -translate-x-1/2';

    return (
      <div className="relative w-full h-full bg-black overflow-hidden">
        {seekOverlay && isHLS && (
          <div className={`absolute top-1/2 -translate-y-1/2 ${overlayPosition} z-30 pointer-events-none`}>
            <div className="min-w-[76px] sm:min-w-[96px] text-center rounded-full bg-black/70 backdrop-blur-md border border-white/10 px-4 py-3 text-white text-lg sm:text-2xl font-extrabold shadow-2xl seek-pop">
              {seekOverlay.side === 'left' ? '⏪ ' : seekOverlay.side === 'right' ? '⏩ ' : '▶ '}{seekOverlay.text}
            </div>
          </div>
        )}

        {/* Error Overlay / State */}
        {playerState.error && isHLS && (
          <div className="absolute inset-0 z-40 flex flex-col items-center justify-center p-6 bg-slate-950/95 backdrop-blur-md text-center">
            <Icons.Lock />
            <h4 className="text-xl font-bold text-white mt-4 mb-2">Protected Class Playback</h4>
            <p className="text-sm text-slate-300 max-w-md mb-6">{playerState.error}</p>
            {playerState.errorType === 'AUTH_REQUIRED' ? (
              <button
                onClick={onRequireLogin}
                className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-400 hover:to-blue-500 px-6 py-2.5 rounded-full font-bold text-white text-sm shadow-xl transition-all"
              >
                Log In with Google
              </button>
            ) : (
              <button
                onClick={() => playAuthenticatedBunnyVideo(video)}
                className="bg-slate-800 hover:bg-slate-700 text-cyan-400 border border-slate-600 px-5 py-2 rounded-full font-semibold text-sm transition-all"
              >
                Retry Access
              </button>
            )}
          </div>
        )}

        {/* Loading Indicator */}
        {playerState.loading && isHLS && (
          <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/70 backdrop-blur-sm text-center">
            <div className="w-10 h-10 border-4 border-cyan-500/30 border-t-cyan-400 rounded-full animate-spin mb-3"></div>
            <p className="text-xs font-semibold text-cyan-400 tracking-wider uppercase">Authenticating Stream...</p>
          </div>
        )}

        {isHLS ? (
          <video
            ref={videoRef}
            className="w-full h-full object-contain"
            playsInline
            preload="metadata"
            onDoubleClick={handleHlsDoubleClick}
            onPointerDown={handleHlsPointerDown}
            onPointerUp={handleHlsPointerUp}
            onPointerCancel={handleHlsPointerUp}
            onPointerLeave={handleHlsPointerUp}
            onTimeUpdate={(e) => {
              const current = e.currentTarget.currentTime;
              const duration = e.currentTarget.duration;
              if (duration > 0 && current / duration >= 0.90) markCompleted();
            }}
          />
        ) : (
          <div className="w-full h-full pointer-events-auto">
            <div id="yt-player" className="w-full h-full" />
          </div>
        )}
      </div>
    );
  };

  // Rest of original quotes
  const quotes = [
    "আজ একটু পড়ি, কাল নিজের উপর গর্ব করতে পারবো — চল শুরু করি।",
    "ধীরে হলেও সমস্যা নেই, আমি প্রতিদিন এক ধাপ এগোচ্ছি।",
    "কষ্ট লাগছে মানে আমি grow করছি — এটা ভালো লক্ষণ!",
    "একদিনের পড়া বাদ দিলে স্বপ্ন একদিন দূরে সরে যায় — তাই আজই বসি।",
    "আমি পারবো — কারণ আমি হাল ছাড়ি না।"
  ];
  const admissionVibe = [
    "আজকের এই কষ্টটাই আমার admission letter হয়ে ফিরবে।",
    "Seat কম, কিন্তু আমার ইচ্ছাশক্তি বেশি।",
    "আমি প্রতিযোগিতায় না, আমি নিজের সেরাটা দিতে নেমেছি।",
    "একটা chance — আর আমি পুরো শক্তি দিয়ে লড়বো。"
  ];
  const allMotivationalQuotes = [...quotes, ...admissionVibe];

  // Main App
  const App = () => {
    const [user, setUser] = useState(null);
    const [watchedVideos, setWatchedVideos] = useState([]);
    const [view, setView] = useState('library');
    const [selectedVideo, setSelectedVideo] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedDashboardSubject, setSelectedDashboardSubject] = useState(lectureData[0].name);
    const [activeSubject, setActiveSubject] = useState(null);
    const [activeChapter, setActiveChapter] = useState(null);
    const subjectRefs = useRef({});
    const chapterRefs = useRef({});
    const [randomQuotes, setRandomQuotes] = useState([]);

    useEffect(() => {
      const shuffled = [...allMotivationalQuotes].sort(() => 0.5 - Math.random());
      setRandomQuotes(shuffled.slice(0, 2));
    }, [selectedVideo]);

    const flatVideos = useMemo(() => {
      let vids = [];
      lectureData.forEach((sub) => {
        sub.chapters.forEach((chap) => {
          chap.links.forEach((link) => {
            vids.push({ ...link, subName: sub.name, chapName: chap.name, id: getVideoId(link.url) });
          });
        });
      });
      return vids;
    }, []);

    const isVideoWatched = (url) => {
      const id = getVideoId(url);
      return isValidVideoId(id) && watchedVideos.includes(id);
    };

    useEffect(() => {
      const unsubscribe = auth.onAuthStateChanged(async (currentUser) => {
        setUser(currentUser);
        if (currentUser) {
          const docRef = db.collection("users").doc(currentUser.uid);
          const docSnap = await docRef.get();
          if (docSnap.exists) setWatchedVideos(docSnap.data().watched || []);
        } else {
          setWatchedVideos([]);
        }
      });
      return () => unsubscribe();
    }, []);

    const markVideoAsWatched = async (videoId) => {
      if (!user || !isValidVideoId(videoId)) return;

      setWatchedVideos(prev => {
        if (prev.includes(videoId)) return prev;

        const newWatched = [...prev, videoId];

        db.collection("users")
          .doc(user.uid)
          .set({ watched: newWatched }, { merge: true })
          .catch(error => console.error("Progress save failed:", error));

        return newWatched;
      });
    };

    const handleLogin = () => auth.signInWithPopup(googleProvider).catch(alert);
    const handleLogout = () => auth.signOut();

    const filteredData = useMemo(() => {
      if (!searchTerm.trim()) return lectureData;
      const lower = searchTerm.toLowerCase();
      return lectureData.map(subject => {
        if (subject.name.toLowerCase().includes(lower)) return subject;
        const chapters = subject.chapters.map(chapter => {
          if (chapter.name.toLowerCase().includes(lower)) return chapter;
          const links = chapter.links.filter(link => link.text.toLowerCase().includes(lower));
          return links.length > 0 ? { ...chapter, links } : null;
        }).filter(Boolean);
        return chapters.length > 0 ? { ...subject, chapters } : null;
      }).filter(Boolean);
    }, [searchTerm]);

    const getSubjectChapterStats = (subject) => {
      let totalChaps = subject.chapters.length;
      let compChaps = 0;
      let compList = [];
      let uncompList = [];

      subject.chapters.forEach(chap => {
        const validLinks = chap.links.filter(link => isValidVideoId(getVideoId(link.url)));
        const isChapComp =
          validLinks.length > 0 &&
          validLinks.every(link => isVideoWatched(link.url));

        if (isChapComp) {
          compChaps++;
          compList.push(chap.name);
        } else {
          uncompList.push(chap.name);
        }
      });

      return { totalChaps, compChaps, compList, uncompList };
    };

    const globalStats = useMemo(() => {
      let total = 0, comp = 0;
      lectureData.forEach(sub => {
        const stats = getSubjectChapterStats(sub);
        total += stats.totalChaps;
        comp += stats.compChaps;
      });
      return { total, comp };
    }, [watchedVideos]);

    const nextVideos = useMemo(() => {
      if (!selectedVideo) return [];
      const currentIndex = flatVideos.findIndex(v => v.id === selectedVideo.id);
      if (currentIndex === -1) return [];

      return flatVideos
        .slice(currentIndex + 1)
        .filter(v => isValidVideoId(v.id) && !watchedVideos.includes(v.id))
        .slice(0, 2);
    }, [selectedVideo, flatVideos, watchedVideos]);

    return (
      <div className="min-h-screen bg-[#020617] bg-[radial-gradient(ellipse_80%_80%_at_50%_-20%,rgba(14,165,233,0.15),rgba(255,255,255,0))] flex flex-col font-sans text-slate-200">

        <header className="sticky top-0 z-50 bg-[#0f172a]/80 backdrop-blur-xl border-b border-white/10 shadow-lg">
          <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <h1 className="text-2xl font-black tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500 animate-float">
              FRB-26 ACS
            </h1>

            <div className="hidden md:flex space-x-2 bg-slate-900/50 p-1 rounded-lg border border-white/5">
              <button onClick={() => setView('library')} className={`flex items-center space-x-2 px-4 py-2 rounded-md font-medium text-sm transition-all ${view === 'library' ? 'bg-cyan-500/20 text-cyan-400 shadow-sm' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Icons.Library /> <span>Library</span>
              </button>
              <button onClick={() => setView('dashboard')} className={`flex items-center space-x-2 px-4 py-2 rounded-md font-medium text-sm transition-all ${view === 'dashboard' ? 'bg-cyan-500/20 text-cyan-400 shadow-sm' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                <Icons.Dashboard /> <span>Dashboard</span>
              </button>
            </div>

            <div className="flex items-center space-x-4">
              {user ? (
                <div className="flex items-center space-x-3 bg-white/5 pl-2 pr-4 py-1.5 rounded-full border border-white/10">
                  <img src={user.photoURL || 'https://via.placeholder.com/40'} alt="Profile" className="w-8 h-8 rounded-full border border-slate-600" referrerPolicy="no-referrer" />
                  <div className="hidden sm:block text-sm">
                    <p className="font-bold text-white truncate max-w-[120px]">{user.displayName}</p>
                  </div>
                  <button onClick={handleLogout} className="ml-2 text-xs font-bold text-red-400 hover:text-red-300 bg-red-400/10 px-3 py-1 rounded-full transition-colors">Out</button>
                </div>
              ) : (
                <button onClick={handleLogin} className="bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 px-5 py-2 rounded-full font-bold text-white text-sm shadow-lg transition-transform hover:scale-105 active:scale-95">
                  Login
                </button>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 w-full max-w-7xl mx-auto p-4 sm:p-6 pb-24">
          <div className="w-full text-center py-4 mb-6 bg-slate-900/60 border border-slate-700/50 rounded-2xl backdrop-blur-sm shadow-[0_0_15px_rgba(16,185,129,0.1)]">
            <h2 className="text-xl sm:text-2xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400 tracking-wide">
              "একদিন সাদা কোটটা আমারই হবে — ইনশাআল্লাহ।"
            </h2>
          </div>

          {view === 'library' && (
            <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 relative">

              <div id="video-player-section" className="xl:col-span-2 space-y-6 scroll-mt-24">
                <div className="relative aspect-video w-full rounded-2xl overflow-hidden shadow-2xl border border-slate-700/50 bg-slate-900 group">
                  <UniversalPlayer
                    key={selectedVideo?.id}
                    video={selectedVideo}
                    user={user}
                    onMarkWatched={markVideoAsWatched}
                    onRequireLogin={handleLogin}
                  />
                </div>

                {randomQuotes.length > 0 && (
                  <div className="grid sm:grid-cols-2 gap-4">
                    {randomQuotes.map((quote, idx) => (
                      <div key={idx} className="bg-slate-800/40 border-l-4 border-cyan-500 p-4 rounded-xl shadow-md backdrop-blur-sm">
                        <p className="text-sm font-medium text-slate-300 italic leading-relaxed">
                          "{quote}"
                        </p>
                      </div>
                    ))}
                  </div>
                )}

                {selectedVideo && (
                  <div className="bg-slate-900/40 backdrop-blur-md rounded-2xl p-5 border border-white/5 shadow-lg">
                    <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                      <span className="bg-cyan-500/20 text-cyan-400 p-1.5 rounded-lg mr-3"><Icons.Play/></span>
                      Up Next
                    </h3>
                    {nextVideos.length > 0 ? (
                      <div className="grid gap-3 sm:grid-cols-2">
                        {nextVideos.map((vid) => (
                          <button 
                            key={vid.id}
                            onClick={() => setSelectedVideo(vid)}
                            className="flex text-left items-start p-3 bg-slate-800/50 hover:bg-slate-700/50 border border-slate-700/50 rounded-xl transition-all group"
                          >
                            <div className="relative w-24 h-16 rounded-md overflow-hidden shrink-0 bg-slate-900 mr-3 border border-slate-700">
                              {vid.url.includes('.m3u8') ? (
                                <img 
                                  src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhgsnbROZ9S_lmIUDcVYp05WasqiVM0dtDKFT1wOBbboY28YPRJkLQxu8R_s0G9-AcDq6o0CyNbHtm2my78R4Gsdd7OsW6q61w5F1uWsFJ9kIh_g7hnuyIW5Gkf1FVN7dpiZDgA9xC8pi-qxo14L1w85AQLp2mhl5_yUVb6-p2Pqe7V6fbVVBDsY7pNOmn-/s1600/ACS-HSC-26-Final-Revision-Batch-all-teacher-1.png" 
                                  alt="ACS Class"
                                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" 
                                />
                              ) : (
                                <img 
                                  src={`https://img.youtube.com/vi/${vid.id}/mqdefault.jpg`} 
                                  alt={vid.text}
                                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" 
                                />
                              )}
                              <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-colors"></div>
                            </div>
                            <div className="flex-1 overflow-hidden">
                              <h4 className="text-sm font-semibold text-white truncate mb-1">{vid.text}</h4>
                              <p className="text-xs text-slate-400 truncate">{formatChapterName(vid.chapName)}</p>
                              <span className="text-[10px] font-bold text-cyan-500 mt-1 uppercase tracking-wider block group-hover:translate-x-1 transition-transform">▶ Watch Next</span>
                            </div>
                          </button>
                        ))}
                      </div>
                    ) : (
                      <div className="text-center p-6 bg-emerald-500/10 border border-emerald-500/20 rounded-xl text-emerald-400 font-medium">
                        🎉 Awesome! You've reached the end of the available classes in this sequence.
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Class list accordion */}
              <div className="xl:h-[calc(100vh-120px)] xl:overflow-y-auto custom-scrollbar xl:pr-2 space-y-4">
                <div className="relative sticky top-0 z-10 bg-[#0f172a] pt-1 pb-4">
                  <input 
                    type="text" 
                    placeholder="Search for classes, subjects..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl py-3 px-4 text-sm text-slate-200 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-cyan-500 shadow-inner"
                  />
                </div>

                {filteredData.length > 0 ? filteredData.map((subject) => {
                  let subTotal = 0, subCompleted = 0;
                  subject.chapters.forEach(chap => {
                    chap.links.forEach(l => {
                      if (!isValidVideoId(getVideoId(l.url))) return;
                      subTotal++;
                      if (isVideoWatched(l.url)) subCompleted++;
                    });
                  });

                  return (
                    <AccordionItem
                      key={subject.name}
                      itemRef={(el) => { subjectRefs.current[subject.name] = el; }}
                      title={formatSubjectTitle(subject.name)}
                      progressInfo={{ completed: subCompleted, total: subTotal }}
                      isSubject={true}
                      isOpen={activeSubject === subject.name}
                      onToggle={() => {
                        if (activeSubject === subject.name) {
                          setActiveSubject(null);
                          setActiveChapter(null);
                        } else {
                          setActiveChapter(null);
                          setActiveSubject(subject.name);
                        }
                      }}
                    >
                      <div className="space-y-3">
                        {subject.chapters.map((chapter) => {
                          const chapTotal = chapter.links.length;
                          const chapCompleted = chapter.links.filter(l => isVideoWatched(l.url)).length;

                          return (
                            <AccordionItem
                              key={chapter.name}
                              itemRef={(el) => { chapterRefs.current[chapter.name] = el; }}
                              title={formatChapterName(chapter.name)}
                              progressInfo={{ completed: chapCompleted, total: chapTotal }}
                              isOpen={activeChapter === chapter.name}
                              onToggle={() => setActiveChapter(activeChapter === chapter.name ? null : chapter.name)}
                            >
                              <div className="space-y-2">
                                {chapter.links.map((link) => {
                                  const isActive = selectedVideo?.id === getVideoId(link.url);
                                  const isFinished = isVideoWatched(link.url);

                                  return (
                                    <button 
                                      key={link.url}
                                      onClick={() => { 
                                        const id = getVideoId(link.url); 
                                        const selected = flatVideos.find(v => v.id === id); 
                                        if (selected) {
                                          setSelectedVideo(selected);
                                          setTimeout(() => {
                                            document.getElementById('video-player-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                          }, 50);
                                        } 
                                      }}
                                      className={`w-full flex items-center p-3 rounded-lg transition-all text-left text-sm font-medium border ${isActive ? 'bg-cyan-900/40 border-cyan-500/50 shadow-[0_0_15px_rgba(6,182,212,0.15)]' : 'bg-slate-800/60 border-slate-700/50 hover:bg-slate-700 hover:border-slate-600'}`}
                                    >
                                      <div className={`shrink-0 mr-3 p-1 rounded-full ${isFinished ? 'bg-emerald-500/20 text-emerald-400' : isActive ? 'bg-cyan-500/20 text-cyan-400' : 'bg-slate-700 text-slate-400'}`}>
                                        {isFinished ? <Icons.Check /> : <Icons.Play />}
                                      </div>
                                      <span className={`flex-1 ${isActive ? 'text-white' : 'text-slate-300'}`}>{link.text}</span>
                                    </button>
                                  );
                                })}
                              </div>
                            </AccordionItem>
                          );
                        })}
                      </div>
                    </AccordionItem>
                  );
                }) : (
                  <div className="text-center py-10 text-slate-500 font-medium">No matches found.</div>
                )}
              </div>
            </div>
          )}

          {view === 'dashboard' && (
            <div className="max-w-4xl mx-auto space-y-8 animate-[fadeIn_0.5s_ease-out]">
              <div className="grid md:grid-cols-2 gap-6">
                <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-8 rounded-3xl border border-slate-700 shadow-2xl flex flex-col items-center justify-center text-center relative overflow-hidden">
                  <div className="absolute -top-24 -right-24 w-48 h-48 bg-cyan-500/10 rounded-full blur-3xl"></div>
                  <img src={user?.photoURL || 'https://via.placeholder.com/100'} referrerPolicy="no-referrer" className="w-24 h-24 rounded-full mb-4 border-4 border-slate-800 shadow-xl z-10" />
                  <h2 className="text-2xl font-bold text-white z-10">{user?.displayName || 'Student'}</h2>
                  <p className="text-slate-400 z-10">{user?.email || 'Sign in to sync progress'}</p>
                  {user && (
                    <button
                      onClick={async () => {
                        if (!window.confirm('Reset all saved class progress? This cannot be undone.')) return;
                        try {
                          await db.collection('users').doc(user.uid).set({ watched: [] }, { merge: true });
                          setWatchedVideos([]);
                        } catch (error) {
                          alert('Could not reset progress. Please try again.');
                          console.error(error);
                        }
                      }}
                      className="mt-4 text-xs font-bold text-red-400 hover:text-red-300 bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-full transition-colors z-10"
                    >
                      Reset Progress
                    </button>
                  )}
                </div>

                <div className="bg-slate-900/50 backdrop-blur-xl p-8 rounded-3xl border border-slate-700/50 shadow-2xl flex flex-col items-center justify-center">
                  <h3 className="text-slate-400 font-semibold mb-6 uppercase tracking-widest text-sm">Overall Progress</h3>
                  <CircularProgress completed={globalStats.comp} total={globalStats.total} size="lg" />
                </div>
              </div>

              <div className="bg-slate-900/60 backdrop-blur-xl rounded-3xl border border-slate-700/50 shadow-2xl p-6 sm:p-8">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 pb-6 border-b border-white/5">
                  <h2 className="text-2xl font-black text-white mb-4 sm:mb-0 flex items-center">
                    <span className="text-2xl mr-3">📚</span> Finished Chapters
                  </h2>

                  <div className="relative">
                    <select 
                      value={selectedDashboardSubject} 
                      onChange={(e) => setSelectedDashboardSubject(e.target.value)}
                      className="appearance-none bg-slate-800 border border-slate-700 text-white py-3 pl-4 pr-10 rounded-xl focus:outline-none focus:ring-2 focus:ring-cyan-500 font-medium cursor-pointer shadow-lg w-full sm:w-64"
                    >
                      {lectureData.map(sub => <option key={sub.name} value={sub.name}>{sub.name}</option>)}
                    </select>
                    <div className="absolute right-3 top-3.5 pointer-events-none text-slate-400"><Icons.ChevronDown open={false} /></div>
                  </div>
                </div>

                {(() => {
                  const activeSub = lectureData.find(s => s.name === selectedDashboardSubject);
                  const stats = getSubjectChapterStats(activeSub);

                  return (
                    <div className="grid lg:grid-cols-12 gap-8">
                      <div className="lg:col-span-4 flex flex-col items-center justify-center bg-black/20 p-6 rounded-2xl border border-white/5">
                        <CircularProgress completed={stats.compChaps} total={stats.totalChaps} size="lg" />
                      </div>

                      <div className="lg:col-span-8 grid sm:grid-cols-2 gap-6">
                        <div className="bg-emerald-900/10 border border-emerald-500/20 rounded-2xl p-5">
                          <h4 className="text-emerald-400 font-bold flex items-center mb-4 border-b border-emerald-500/10 pb-2">
                            <Icons.Check /> <span className="ml-2">Completed ({stats.compList.length})</span>
                          </h4>
                          <ul className="space-y-3 max-h-64 overflow-y-auto custom-scrollbar pr-2">
                            {stats.compList.length > 0 ? stats.compList.map(name => (
                              <li key={name} className="flex items-start text-sm text-slate-300">
                                <span className="text-emerald-500 mr-2 mt-0.5">✓</span> {formatChapterName(name)}
                              </li>
                            )) : <li className="text-sm text-slate-500 italic">No chapters completed yet.</li>}
                          </ul>
                        </div>

                        <div className="bg-slate-800/30 border border-slate-700/50 rounded-2xl p-5">
                          <h4 className="text-slate-300 font-bold flex items-center mb-4 border-b border-white/5 pb-2">
                            <span className="text-lg mr-2">⏳</span> Remaining ({stats.uncompList.length})
                          </h4>
                          <ul className="space-y-3 max-h-64 overflow-y-auto custom-scrollbar pr-2">
                            {stats.uncompList.length > 0 ? stats.uncompList.map(name => (
                              <li key={name} className="flex items-start text-sm text-slate-400">
                                <span className="text-slate-600 mr-2 mt-0.5">○</span> {formatChapterName(name)}
                              </li>
                            )) : <li className="text-sm text-emerald-400 italic">All chapters completed!</li>}
                          </ul>
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>
            </div>
          )}

          <footer className="w-full mt-16 pt-8 pb-4 border-t border-slate-800/60 flex flex-col items-center justify-center space-y-4">
            <div className="text-slate-500 text-sm font-medium text-center">
              © {new Date().getFullYear()} Tausif Rahaman Raiyan. All rights reserved.
            </div>
          </footer>
        </main>

        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-[#0f172a]/90 backdrop-blur-xl border-t border-slate-800 pb-safe z-50">
          <div className="flex justify-around items-center h-16 px-2">
            <button onClick={() => setView('library')} className={`flex flex-col items-center justify-center w-full h-full space-y-1 ${view === 'library' ? 'text-cyan-400' : 'text-slate-500'}`}>
              <Icons.Library />
              <span className="text-[10px] font-bold tracking-wide">Library</span>
            </button>
            <button onClick={() => setView('dashboard')} className={`flex flex-col items-center justify-center w-full h-full space-y-1 ${view === 'dashboard' ? 'text-cyan-400' : 'text-slate-500'}`}>
              <Icons.Dashboard />
              <span className="text-[10px] font-bold tracking-wide">Dashboard</span>
            </button>
          </div>
        </div>
      </div>
    );
  };

  const rootElement = document.getElementById('root');
  const root = ReactDOM.createRoot(rootElement);
  root.render(<App />);
//
